  // ── /about — opening (origin + Star Wars crawl) ──
  'about.origin.title': 'A Origem',
  'about.origin.sub': 'Desliza e lê',
  'about.origin.skip': 'ou salta',
  'about.crawl.intro': 'Há dez anos, num abrigo no coração da Europa….',
  'about.crawl.episode': 'Episódio I',
  'about.crawl.faith': 'Uma Nova Fé',
  'about.crawl.p1':
    'Em 2016, oito cachorros pretos chegaram ao abrigo, atirados fora dentro de uma única caixa. Sete encontraram lar. O maior ninguém quis — esperou um ano inteiro. Chamava-se Hekthor.',
  'about.crawl.p2':
    'Um dia, um casal foi ao abrigo ver a Sindy, uma cadela pequena e branca que queriam adotar. Por puro acaso, o Hekthor estava no canil dela na altura — o seu próprio estava a ser limpo. O homem, que só tinha ido por companhia e nunca quisera um cão, apaixonou-se pelo cão preto que via pela primeira vez na vida.',
  'about.crawl.p3':
    'Uma semana depois estavam juntos e começou uma bela história. Toda a vida do homem mudou e, com o tempo, percebeu uma coisa: só quem tem um cão, e sabe o que é o amor de um cão, pode realmente ajudar cães em necessidade.',
  'about.crawl.p4':
    'E foi assim que nasceu o Heroglyph — um símbolo destinado a unir amantes de cães de toda a parte na maior comunidade que o mundo alguma vez conheceu. Uma comunidade que vai estar do nosso lado, do lado dos nossos cães e das gerações que hão de vir — por pessoas que não têm medo de admitir que um cão não é apenas um animal, mas um ser que nos torna humanos melhores.',
  'about.crawl.p5':
    'Neste preciso momento, começa a jornada rumo ao primeiro marco — criar 1 000 000 de Heroglyphs. E tu podes fazer parte dela. Porque os únicos suficientemente loucos para acreditar que podem mudar o mundo são aqueles que o fazem.',
  'about.crawl.p6': 'IN DOG WE TRUST.',

  // ── /about — timeline (5 milestones) ──
  'about.timeline.heading': 'A História da Dogypt',
  'about.milestone.1.year': '2017',
  'about.milestone.1.tag': 'O Abrigo',
  'about.milestone.1.title': 'Tesouro no Abrigo',
  'about.milestone.1.body':
    'Um cão preto que ninguém queria esperava atrás da vedação de um abrigo. O seu nome tornou-se Hekthor. Adotá-lo não foi um resgate — foi o começo de tudo.',
  'about.milestone.2.year': '2018',
  'about.milestone.2.tag': 'O Laço',
  'about.milestone.2.title': 'Um Laço para Sempre',
  'about.milestone.2.body':
    'Puxou-me pela fase mais dura da minha vida sem dizer uma única palavra. Todo o amante de cães conhece isto — seguram-te exatamente quando estás a cair.',
  'about.milestone.3.year': '2019',
  'about.milestone.3.tag': 'A Jornada',
  'about.milestone.3.title': 'A Caminhada que Se Tornou um Livro',
  'about.milestone.3.body':
    'Juntos atravessámos a Eslováquia — 42 dias, 800 quilómetros, uma promessa silenciosa. Essa estrada tornou-se um livro: „Cesta s Hrdinom" — A Estrada com um Herói.',
  'about.milestone.4.year': '2022',
  'about.milestone.4.tag': 'O Nome',
  'about.milestone.4.title': 'Uma Nação de Amantes de Cães',
  'about.milestone.4.body':
    'Pirâmides, misticismo, a glória eterna do Egito — a humanidade está enfeitiçada há milénios. Une isso ao amor infinito de um cão e obténs a DOGYPT. Selei a ideia na Expo Dubai 2022, vestido de faraó.',
  'about.milestone.5.year': 'Agora',
  'about.milestone.5.tag': 'Dogypt',
  'about.milestone.5.title': 'A Jornada Começa Contigo',
  'about.milestone.5.body':
    'A DOGYPT é um movimento para todos cuja vida foi mudada por um cão. Construída sobre o laço mais antigo e mais honesto da Terra. O Hekthor é o fundador #1. Tu és o próximo.',

  // ── /about — outro + reel ──
  'about.outro.quoteLead': 'Nunca Foi',
  'about.outro.quoteTail': '"Apenas um Cão."',
  'about.outro.body':
    'Já conheces a sensação — que um cão não é algo que possuis, é <strong>alguém que amas</strong>. Agora imagina esse amor organizado, ligado, <strong>poderoso o suficiente para mudar as coisas.</strong> E é por isso que existe a <strong>DOGYPT</strong>.',
  'about.outro.name1': 'Matej',
  'about.outro.and': 'e',
  'about.outro.name2': 'Hekthor',
  'about.outro.cta': 'Torna-te dogípcio',
