  'about.council.imgAlt': 'Um faraó com o Hekthor e os seus gatos — a Dogypt precisa de ti',
  'about.council.headline': 'Precisa de Ti.',
  'about.council.sub':
    'A DOGYPT é construída por pessoas que sabem o que significa um cão. Se tens algo a trazer — uma competência, uma voz, uma visão — é aqui que pertence.',
  'about.council.rolesAria': 'Escolhe o teu papel',
  'about.council.role.dog-lover.label': 'Amante de Cães e Tester',
  'about.council.role.dog-lover.desc': 'Acesso antecipado e feedback honesto',
  'about.council.role.developer.label': 'Programador / Designer',
  'about.council.role.developer.desc': 'Cria funcionalidades, desenha visuais',
  'about.council.role.dog-pro.label': 'Profissional de Cães',
  'about.council.role.dog-pro.desc': 'Veterinário, treinador, abrigo, criador',
  'about.council.role.creator.label': 'Criador',
  'about.council.role.creator.desc': 'Vídeo, foto, arte para a matilha',
  'about.council.role.media.label': 'Média / Influencer',
  'about.council.role.media.desc': 'Audiência e cobertura',
  'about.council.role.investor.label': 'Investidor',
