  "heroglyph.flow.dogCharacter.slideLabel": "SLIDE",
  "heroglyph.flow.dogCharacter.slideAriaLabel": "Próximo slide de personagem",
  "heroglyph.flow.dogCharacter.slide.guardian.title": "Guardião (Olho de Dogo)",
  "heroglyph.flow.dogCharacter.slide.player.title": "Brincalhão (Bola alada)",
  "heroglyph.flow.dogCharacter.slide.energizer.title": "Hiperativo (Bateria cheia)",
  "heroglyph.flow.dogCharacter.slide.maverick.title": "Rebelde (Símbolo pirata)",
  "heroglyph.flow.dogCharacter.slide.waterlover.title": "Aquático (Ondas)",
  "heroglyph.flow.dogCharacter.slide.gourmet.title": "Guloso (Tigela infinita)",
  "heroglyph.flow.dogCharacter.slide.lover.title": "Meigo (Amor)",
  "heroglyph.flow.dogCharacter.slide.chiller.title": "Sossegado (Sofá)",
  "heroglyph.flow.dogCharacter.slide.guardian.desc": "Guarda a porta como se fossem os portões do além. Primeiro ladra, perguntas nunca.",
  "heroglyph.flow.dogCharacter.slide.player.desc": "Vende a alma por mais um lançamento da bola. Maior alegria: o brinquedo preferido.",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "Sem botão de desligar. Sem pilhas. A pergunta mais frequente: o que é que este cão anda a tomar?",
  "heroglyph.flow.dogCharacter.slide.maverick.desc": "Pirata moderno com mundo próprio e regras próprias. A audição seletiva é a sua primeira lei.",
  "heroglyph.flow.dogCharacter.slide.waterlover.desc": "Há dois tipos de cães — e um pode ser confundido com um peixe. Pelo molhado: 100% felicidade.",
  "heroglyph.flow.dogCharacter.slide.gourmet.desc": "A comida é a missão. Entrega total, zero hesitação — e ainda come o que tu deixaste.",
  "heroglyph.flow.dogCharacter.slide.lover.desc": "Para ele não há estranhos. Recebe o carteiro como uma alma gémea há muito perdida. Sempre.",
  "heroglyph.flow.dogCharacter.slide.chiller.desc": "Domina a antiga arte de não fazer absolutamente nada — e com estilo.",
  "heroglyph.flow.message.done": "Feito",
