  "heroglyph.flow.more.ainubis.d": "A nossa IA personalizada, o teu ajudante e mentor. Conhece o teu cão de cor e salteado. Aprende com as suas fontes, consulta-as e contribui com os teus próprios materiais e experiência.",
  "heroglyph.flow.more.ainubis.t": "AINUBIS",
  "heroglyph.flow.more.cause.d": "A DOGYPT facilita a vida aos amantes de cães, mas também junta boas pessoas e ajuda cães em necessidade, com toda a transparência. Até o fundador da DOGYPT, o HEKTHOR, veio de um abrigo.",
