  "heroglyph.flow.more.dogid.d": "O perfil completo do teu cão num só lugar. Tudo o que preencheres, o nosso AINUBIS aproveita. Um «boletim» útil sempre à mão, por exemplo no veterinário.",
  "heroglyph.flow.more.dogid.t": "DOG ID",
  "heroglyph.flow.more.dogtrip.d": "Aventuras dog friendly de todo o mundo num só lugar. Adiciona o teu passeio favorito e partilha-o com a matilha. Inspira-te nos outros, junta pontos, crachás e níveis.",
