  "heroglyph.flow.more.eyebrow": "Adesão à DOGYPT",
  "heroglyph.flow.more.glyph.d": "Um símbolo único que capta o teu cão na perfeição. Uma linguagem universal feita para unir os amantes de cães. A tua chave da DOGYPT.",
  "heroglyph.flow.more.glyph.t": "HEROGLYPH",
  "heroglyph.flow.more.money.d": "De cada €11, €5 vão para o desenvolvimento, €3 para a comunidade, €2 para o resgate de cães e €1 para a tigela do Hekthor. Cada despesa será documentada e pública.",
