  "heroglyph.flow.more.next": "Seguinte",
  "heroglyph.flow.more.pack.d": "Acesso a uma plataforma criada para amantes de cães. A app não para de crescer e vai servi-los em todas as frentes.",
  "heroglyph.flow.more.pack.t": "ÁREA DE MEMBROS",
  "heroglyph.flow.more.prev": "Anterior",
  "heroglyph.flow.more.sniffer.d": "Encontra um parceiro, um par ou um grupo para passeios, voltas regulares ou uma road trip cheia de aventura. Um serviço de encontros feito especialmente para cães e os seus humanos.",
