  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. Dentro da Matilha: o que outros Membros veem",
  "privacy.s12.body": "O artigo 3 descreve o GodsGrid público. Dentro da Matilha — a área só para Membros — outros Membros com sessão iniciada veem mais: o teu primeiro nome, o teu número dogípcio, o nome e a foto do teu cão, os atributos que preencheste sobre o teu cão, as viagens que registaste ou anunciaste, as tuas avaliações e comentários, e o que escreveste no teu perfil. Não veem o teu endereço de e-mail, o teu endereço postal, os teus dados de pagamento nem as tuas mensagens com qualquer outra pessoa. Quando anuncias uma viagem como aberta, o trilho, a data e o teu cão tornam-se visíveis para todos os Membros, para que possam pedir para se juntar — é isso que significa anunciá-la. Uma viagem que mantens privada só é vista por ti e pelas pessoas que já vão. Tu escolhes qual das duas opções é, e podes mudar isso em qualquer momento.",
  "privacy.s13.title": "13. Mensagens e Denúncias",
  "privacy.s13.body": "As mensagens privadas entre Membros são guardadas na nossa base de dados (Supabase) para que as conversas sobrevivam entre sessões. Base legal: art.º 6.º, n.º 1, alínea b) do RGPD — fazem parte da adesão que pagaste. Não as lemos de forma rotineira e nunca as usamos para publicidade ou perfilamento. Só abrimos uma conversa quando é denunciada, quando investigamos um abuso ou incidente de segurança específico, ou quando a lei o exige. Uma denúncia guarda o motivo que escolheste, a tua nota opcional e uma referência ao que denunciaste — não uma cópia separada disso. O bloqueio é guardado como um par de identificadores de membro. Se eliminares a tua conta, as tuas mensagens vão com ela; a cópia no tópico da outra pessoa permanece, mostrada como vinda de um membro removido, porque essa conversa também é dela.",
  "terms.s12.title": "12. Conteúdo que publicas",
  "terms.s12.body": "Ao lado do teu HEROGLYPH podes publicar conteúdo dentro da Matilha: fotos de viagens, rotas e locais, descrições de viagens, avaliações, comentários e perguntas, e o que escreveres no teu perfil. Quando marcas uma viagem como percorrida, outros Membros veem o teu primeiro nome e os cães que a percorreram contigo. Mantens a propriedade de tudo o que publicas. Ao publicá-lo, concedes à DOGYPT s.r.o. uma licença mundial, sem royalties e não exclusiva para armazenar, mostrar e adaptar esse conteúdo com o propósito de operar e promover o Serviço — por exemplo, mostrar a foto da tua viagem no mapa, numa listagem de viagens ou num cartão para partilhar. A licença dura enquanto o conteúdo estiver no Serviço; ao removeres o conteúdo ou a tua conta, termina, exceto nas cópias de segurança, que expiram no seu ciclo normal. Não vendemos o teu conteúdo nem o licenciamos a mais ninguém para uso próprio. Publica apenas aquilo que tens direito de publicar — isso inclui fotos tiradas por outra pessoa e pessoas reconhecíveis nelas.",
  "terms.s13.title": "13. Mensagens entre Membros",
  "terms.s13.body": "Os Membros podem escrever diretamente uns aos outros. As mensagens são privadas entre os participantes — não as lemos de forma rotineira e nunca as usamos para publicidade. São guardadas nos nossos servidores para que a conversa continue lá quando voltares, e podemos ler uma conversa em três casos: quando alguém a denuncia, quando investigamos um abuso ou incidente de segurança específico, ou quando a lei o exige. Podes bloquear outro Membro em qualquer momento; o bloqueio é imediato e funciona nos dois sentidos. Trata as mensagens como qualquer conversa online — não envies dados de pagamento, senhas ou documentos que não queiras que fiquem guardados.",
  "terms.s14.title": "14. Denúncias e Moderação",
  "terms.s14.body": "Perfis, viagens e conversas podem ser denunciados. Uma denúncia chega até nós e é lida por uma pessoa — hoje é o fundador, Matej Stacho. O nosso objetivo é analisar cada denúncia em 7 dias. Dependendo do que encontrarmos, podemos não fazer nada, remover o conteúdo, avisar o Membro, limitar o que ele pode publicar ou encerrar a conta. Se agirmos sobre o teu conteúdo, diremos porquê por e-mail, e podes responder e contestar. Também podemos remover conteúdo por iniciativa própria quando viola o artigo 7. Abuso deliberado ou repetido — assédio, spam, viagens falsas, conteúdo envolvendo menores — encerra a conta sem aviso adicional.",
