  "pack.cal.life.recSince": "desde {year}",
  "pack.cal.life.tip.weight.title": "Manter-se magro é a única coisa que está provada",
  "pack.cal.life.tip.weight.body": "De tudo o que podes fazer por um cão, uma coisa tem a prova mais sólida sobre a longevidade: não o deixar ganhar peso. A diferença entre um cão magro e um ligeiramente obeso são anos, não meses. Deves conseguir sentir as costelas sem pressionar.",
  "pack.cal.life.tip.move.title": "Movimento em terreno real, não uma volta ao quarteirão",
  "pack.cal.life.tip.move.body": "O terreno irregular mantém as articulações, os músculos e a mente ativos. Cada viagem que registas transforma-se numa semana escura nesta grelha — e as semanas escuras são a única coisa que realmente podes influenciar.",
  "pack.cal.life.tip.food.title": "Comida que o cão reconhece como comida",
  "pack.cal.life.tip.food.body": "Quantos menos passos houver entre o ingrediente cru e a tigela, menos coisas podem correr mal pelo caminho. A ração não é um pecado, mas também não é uma dieta — é um atalho.",
  "pack.cal.life.tip.chem.title": "Química só quando é mesmo necessária",
  "pack.cal.life.tip.chem.body": "Os antiparasitários todo o ano, a anestesia por conveniência e os antibióticos «por precaução» são decisões, não rotina. Pergunta, para cada um: o que acontece se eu não der? Onde a resposta for «nada», não dês.",
  "pack.cal.life.tip.stress.title": "O descanso conta tanto como o movimento",
  "pack.cal.life.tip.stress.body": "Um cão que está sempre alerta queima o corpo por dentro. Dormir sem ser perturbado, um dia previsível e calma depois do esforço não são preguiça — são as horas em que o corpo se repara.",
  "pack.cal.life.tip.protocol.title": "Um protocolo em vez de uma corrida em pânico ao veterinário",
  "pack.cal.life.tip.protocol.body": "A desparasitação, a coprologia e as análises de sangue têm as suas próprias janelas no calendário. Um cão a quem verificas o sangue duas vezes por ano não está a ser tratado — está a ser mantido à frente do problema.",
  "pack.cal.life.tip.joints.title": "As articulações são tratadas ANTES de começarem a doer",
  "pack.cal.life.tip.joints.body": "O teu cão já está na faixa sénior. A cura para as articulações tem a sua janela no calendário a partir de novembro — não porque esteja a coxear, mas para que nunca precise.",
