  "pack.hero.popLevelEyebrow": "Nível",
  "pack.hero.popLevelTitle": "{name} · nível {index} de 22",
  "pack.hero.popLevel1": "O teu nível de devoção sobe com as boas ações feitas pela raça canina — passeios, cuidados, uma mão estendida a um cão em necessidade.",
  "pack.hero.popLevel2": "A escada tem 22 degraus, iguais para todos, e nenhum pode ser comprado. A contagem começa quando a DOGYPT passar para a app móvel.",
  "pack.hero.popLevelStamp": "Começa a contar com a app",
  "pack.hero.popBonesEyebrow": "Moeda",
  "pack.hero.popBones1": "Os BONES são a moeda da DOGYPT. Hoje ganhas-los trazendo mais alguém — um amigo dá-te +20 🦴, e quando esse amigo trouxer outro, +10 🦴 mais. Vês-los aqui mesmo, neste selo.",
  "pack.hero.popBones2": "Em que os vais gastar está a ser construído — merchandising, angariações para abrigos, créditos de IA. Nada do que juntares agora se perde.",
  "pack.hero.popBonesCta": "Convidar um amigo",
