  "pack.hero.popDevotion1": "A Devoção (☥) mede o que realmente dás ao teu cão — presença, passeios, rituais diários.",
  "pack.hero.popDevotion2": "Vais poder juntá-la quando tiveres a app à mão todos os dias. Até lá seria um medidor que mede o vazio.",
  "pack.hero.popDevotionStamp": "Desbloqueia com a app · 2027",
  "pack.heroBadge.more": "Mais sobre a história →",
  "pack.heroBadge.trips": "{n} viagens",
  "pack.heroBadge.kickerMilestone": "Marco alcançado",
  "pack.heroBadge.kickerEarned": "Distintivo de herói",
  "pack.heroBadge.kickerLocked": "{n} viagens mais para desbloquear",
  "pack.heroBadge.hachiko.story": "Nove anos, nove meses, quinze dias. Foi assim que o akita Hachikō esperou na estação de Shibuya por um homem que nunca voltou. O professor Hidesaburō Ueno adotou-o em 1924 e levava-o à estação todas as manhãs, indo buscá-lo ali todas as tardes — um ritual que terminou a 21 de maio de 1925, quando o professor morreu a meio de uma aula. O Hachikō não sabia. Foi à estação nessa noite, e na seguinte, e um ano depois, e nove anos mais tarde. Não esperava por uma ordem nem por uma recompensa — esperava porque a lealdade de um cão não segue a lógica, segue o laço. O Japão ergueu-lhe uma estátua ainda em vida. O Hachikō não é apenas um cão. É uma liturgia de lealdade, celebrada numa plataforma de estação.",
  "pack.heroBadge.barry.story": "No Grande Passo de São Bernardo, onde o gelo não perdoa nada e a névoa rouba o caminho, serviu um São Bernardo chamado Barry. Durante doze anos caminhou onde outros temiam pisar — até tempestades de neve a 2.500 metros, procurando viajantes perdidos antes que a neve os levasse. Não foi treinado para uma ordem. A sua vocação estava escrita sob o pelo. Salvou mais de quarenta vidas. A lenda diz que morreu pela mão do quadragésimo primeiro homem que tentou resgatar; a verdade é mais humilde — viveu os seus últimos dias em paz em Berna. A DOGYPT honra-o não pelo mito do martírio, mas pela coisa real: um cão que escolheu caminhar para a tempestade em vez de ficar onde estava quentinho.",
  "pack.heroBadge.togo.story": "Enquanto o mundo se inclinava perante o Balto, o verdadeiro herói já há muito dormitava numa vitrine de museu no Alasca. Togo, um husky siberiano de doze anos feito de cicatrizes, liderou a equipa de Leonhard Seppala através do troço mais longo e mortal da corrida do soro — mais de 260 milhas de gelo, escuridão e vento. O Balto levou a gloria pelas últimas 55 milhas, a estátua em Central Park e as manchetes. O Togo levou o Norton Sound — o estreito gelado que começou a romper-se sob as suas patas, e que ainda assim atravessou, fazendo a sua equipa nadar pelas fendas até à segurança. A DOGYPT não se ajoelha perante a fama fabricada para as câmaras — ajoelha-se perante o cão que fez o trabalho quando ninguém estava a ver.",
  "pack.heroBadge.hekthor.story": "Ninguém o queria. Sete cachorros numa caixa, um homem que não tinha planeado ter um cão — e ainda assim a faísca saltou para ele. Foi assim que o Hekthor começou em 2017: uma coisa preta e peluda nascida da necessidade, que escolheu o seu humano antes que o humano o pudesse escolher a ele. Daquele acaso nasceu um caminho — literalmente. Quarenta e dois dias pela Eslováquia, quilómetro a quilómetro, através de cadeias montanhosas e vales. Do caminho nasceu um livro. Do livro nasceu a DOGYPT. O Hekthor não é uma mascote nem um logótipo — é o cão zero, a prova de que uma única vida resgatada pode pôr em marcha todo um movimento. Os seus quarenta e dois dias são o modelo do caminho que todo o dogípcio percorre: não em direção ao desempenho, mas em direção à ligação.",
  "pack.heroBadge.bothie.story": "Era um cão vadio qualquer — um Jack Russell terrier de pelo longo que Ranulph e Ginny Fiennes encontraram em 1977. Dois anos depois estava no convés de um navio rumo a uma expedição que o mundo nunca tinha visto: a Transglobe, a primeira viagem à volta da Terra ao longo do seu meridiano, pelos dois polos, inteiramente pela superfície. Saltou a África — calor demais para um cão — mas quando a expedição chegou ao gelo, o Bothie estava lá. Nove meses na Antártida, e a 10 de abril de 1982 pisou o Polo Norte. O único cão na história a pisar os dois extremos do mundo. A DOGYPT recorda-o não porque sobreviveu aos polos, mas porque provou que a lealdade e a curiosidade vão mais longe do que a maioria dos planos humanos.",
  "pack.heroBadge.laika.story": "Antes de qualquer humano, foi ela que voou. A 3 de novembro de 1957 deixou as ruas de Moscovo, e dias depois também o céu — na cabine da Sputnik 2, construída em menos de um mês, sem qualquer plano de regresso. Laika, uma cadela vadia que pesava apenas cinco quilos, tornou-se a primeira criatura em órbita. A propaganda soviética falava de um voo tranquilo. A verdade — que morreu na quarta órbita, quando a cabine aqueceu a quarenta graus — só veio à luz em 2002, depois de 45 anos de silêncio. É por isso que é uma heroína da DOGYPT: não porque venceu, mas porque sequer chegou a decolar. Em 2008, Moscovo deu-lhe um monumento: uma pata a subir até ao topo de um foguetão.",
  "pack.heroBadge.bobbie.story": "Em agosto de 1923, o Bobbie, um cruzamento de collie e pastor, separou-se da família Brazier numa bomba de gasolina no Indiana — a 4.100 quilómetros de casa. A família procurou, colou cartazes e por fim voltou para casa de mãos vazias. O Bobbie não desistiu. Durante seis meses caminhou sozinho por uma América gelada — atravessando rios a nado, cruzando a Divisória Continental em pleno inverno, alimentado por pessoas que o notavam em acampamentos ao longo do caminho. Em fevereiro de 1924 entrou no restaurante da sua família em Silverton como se tivesse só saído por um momento. Esta não é uma história sobre sorte. É a prova de que o caminho de casa se pode percorrer mesmo quando ninguém acredita que seja possível — passo a passo, sem mapa, com a lealdade como bússola.",
  "pack.heroBadge.seaman.story": "Enquanto a maioria dos homens do Corps of Discovery pedia salário, o Seaman só pedia um lugar junto ao fogo. Meriwether Lewis comprou-o em Pittsburgh em 1803 por vinte dólares — meio salário mensal de capitão por um único terra-nova. Valeu a pena. Três anos, através de um continente, pelo Missouri, pelas Rocosas e até ao Pacífico — e o Seaman foi o único animal a fazer a viagem toda. Caçava, fazia guarda de noite contra ursos, uma vez afugentou um bisão do acampamento. Quando um castor lhe rasgou a artéria com uma mordida, foi o próprio Clark que o costurou. Quando o roubaram, Lewis enviou três homens para o trazerem de volta — não se abandona um cão. Os diários da expedição mencionam-no pelo nome mais vezes do que a maioria dos soldados.",
  "pack.heroBadge.savannah.story": "Savannah não é uma lenda inventada para efeito — é uma cadela que realmente deu a volta ao planeta a pé. Tom Turcich tirou-a de uma vala à beira de uma estrada no Texas quando era uma cachorrinha de quatro meses. Quatro meses antes, ele tinha partido numa viagem a pé à volta do mundo; a Savannah juntou-se a ele, e desde esse dia nunca deu um passo ao lado dele que não levasse à meta. Sete anos, seis continentes, dezenas de países, centenas de milhares de quilómetros — sob chuva, com calor, sobre os Andes, pela areia. Sem reclamar, com o rabo ao alto. Tornou-se a primeira e, até agora, única cadela a dar a volta ao mundo a pé. Em 2024, com nove anos, morreu em casa — depois de uma viagem que nenhum outro cão fez alguma vez. Savannah = 1000 viagens não é uma metáfora. Para ela, seria ficar por baixo.",
