  "pack.nature.balance.body": "A constituição do teu cão está definida para toda a vida, mas pode desequilibrar-se. Marca tudo o que se aplica — tanto ou tão pouco como quiseres.",
  "pack.nature.balance.none": "Nada da lista? Deixa vazio e continua — essa é a melhor resposta que existe.",
