  "pack.nature.ans.no": "Não",
  "pack.network.ads.body": "Os anúncios pagos são uma forma muito ineficiente de encontrar novos amantes de cães — e uma maneira de atirar o nosso dinheiro para grandes corporações. Funciona muito melhor recompensar diretamente os membros do movimento por estarem ativos. Há um truque: <strong style=\"font-weight:600\">só funciona mesmo se saíres e falares de nós às pessoas à tua volta</strong> :)",
  "pack.network.ads.header": "Porque desta forma?",
  "pack.network.ads.wordAd": "um anúncio",
