  "pack.network.capped.none": "Sem devoção deste — os teus presentes já igualam tudo o que viveste. Os BONES são enviados da mesma forma. <i>O dinheiro duplica os anos, nunca os substitui.</i>",
  "pack.network.capped.room": "Limite em <b style=\"color:#2a1608\">{room}</b> — um presente só pode igualar o que viveste ({lived} de devoção até agora). Os BONES são enviados da mesma forma; a honra espera pelos dias.",
