  "pack.network.emptyLine": "Ainda ninguém — o primeiro nome aqui é o início da tua linha.",
  "pack.network.eyebrow": "A DOGYPT cresce graças a ti",
  "pack.network.generatingLink": "A gerar o teu link…",
