  "pack.network.groupTheirBrings": "os que trouxeram",
  "pack.network.inLine": "Na tua linha",
  "pack.network.info.bones.body": "BONES é a moeda interna da DOGYPT — um nome brincalhão para uma coisa real. Um cão paga em ossos; nós também. <b>Ganhas</b> os teus trazendo amantes de cães para a matilha e fazendo o movimento avançar, e <b>gastas</b> dentro da DOGYPT: apoiando angariações para abrigos, obtendo merchandising, e mais tarde pagando a outros dogípcios pelo que criam. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "O que é o BONES?",
  "pack.network.info.why.body": "Um movimento deste tamanho não se pode comprar — nenhum orçamento chega a um estranho como um dogípcio chega a um amigo. Por isso a matilha põe a recompensa onde está o alcance: em ti. Quando alguém se junta através do teu link, ganhas <b>{l1} BONES</b>; quando essa pessoa trouxer outra, ganhas mais <b>{l2}</b>. Cada dogípcio que espalha a palavra não é um vendedor — é um missionário, e honramos esse trabalho.",
  "pack.network.info.why.cap": "Porque te pedimos isto",
  "pack.network.intro": "Um movimento só cresce quando os seus membros levam a mensagem e trazem gente nova. Por isso pedimos-te diretamente: <strong style=\"color:#2a1608;font-weight:600\">convida os amantes de cães que conheces</strong>. Aqui está exatamente como funciona.",
  "pack.network.inviteLinkHeader": "O teu link de convite",
  "pack.network.listSummary": "{n} pessoas · {b} BONES ganhos",
