  "pack.network.step2Body": "Se alguém forjar um <strong style=\"color:#2a1608;font-weight:600\">Heroglyph</strong> através do teu link, ganhas <strong style=\"color:#2a1608;font-weight:600\">{l1} BONES</strong>. Se esse membro também trouxer alguém, ele ganha {l1} e <strong style=\"color:#2a1608;font-weight:600\">tu ganhas mais {l2}</strong>.",
