  "onepage.hbook.0.title": "Era uma vez…",
  "onepage.hbook.0.glyph": "O heroglyph do Hekthor",
  "onepage.hbook.0.sub": "Hekthor · cão #1",
  "onepage.hbook.0.cap": "O espelho",
  "onepage.hbook.1.ini": "N",
  "onepage.hbook.1.lead": "asceu indesejado. Atirado para uma caixa, onde esperava a morte com os irmãos.",
  "onepage.hbook.1.txt": "Oito almazinhas foram parar a um canil. Sete encontraram um lar. Só um ficou para trás — o maior, com o maior temperamento. Um ano depois, por puro acaso, conheceu o Matej, que nunca tinha planeado ter um cão. Saltou uma faísca e, desde junho de 2017, caminham juntos pela vida.",
  "onepage.hbook.1.cap": "Oito numa caixa",
  "onepage.hbook.2.ini": "S",
  "onepage.hbook.2.lead": "alvou uma vida humana. Chegou na época mais difícil dela.",
  "onepage.hbook.2.txt": "Nos tempos mais sombrios foi a âncora do Matej — tirou-o dos pensamentos escuros, do apartamento e levou-o para a natureza. Primeiro as ruas próximas, depois florestas e montanhas. Atravessaram toda a Eslováquia (820 km) e fizeram viagens de carro pela Europa. A aventura e uma vida livre na estrada uniram-nos.",
  "onepage.hbook.2.cap": "Do escritório para o mundo",
  "onepage.hbook.3.ini": "E",
  "onepage.hbook.3.lead": "le, com a sua alma pura, trouxe a visão de um movimento global para os amantes de cães.",
  "onepage.hbook.3.txt": "A vida com um cão é o capítulo mais bonito da vida de qualquer pessoa. Os amantes de cães são outro tipo de gente — resolvem sempre os mesmos problemas específicos e unem-nos o amor pelos cães. E se esta história se tornasse algo útil?",
  "onepage.hbook.3.cap": "Nasce uma visão",
  "onepage.hbook.4.ini": "D",
  "onepage.hbook.4.lead": "ez anos lindos para trás, e pelo menos mais dez pela frente!",
  "onepage.hbook.4.txt": "O Hekthor inspirou o Matej a aprender tudo sobre cães — psicologia, treino, desporto e, acima de tudo, longevidade. Todo esse conhecimento servirá a todos no DOGYPT: não mais uma rede social da moda, mas uma com conteúdo que faz sentido. E tudo por causa de um cão «normal» de canil.",
  "onepage.hbook.4.cap": "Fundador #1",
  "onepage.hbook.5.ini": "H",
  "onepage.hbook.5.lead": "oje vive na Eslováquia — nas florestas, nas montanhas e junto aos lagos.",
  "onepage.hbook.5.txt": "Ir buscar a bola à água é o seu maior amor. Está em grande forma, é sábio, humilde e o melhor companheiro que qualquer pessoa podia desejar. Quando não estamos fora, vigia em casa dois gatos, o Gary e o Yby, que salvou da rua.",
  "onepage.hbook.5.cap": "Guardião do lar",
